/* @lc app=leetcode id=3250 lang=kotlin */ class Solution { fun countOfPairs(nums: IntArray): Int = nums.indices.drop(1).fold(LongArray(nums[0] + 1) { 1L }) { dp, i -> maxOf(0, nums[i] - nums[i - 1]).let { d -> dp.runningFold(0L) { s, v -> (s + v) % 1_000_000_007 }.let { pre -> LongArray(nums[i] + 1) { a -> if (a - d < 0) 0L else pre[minOf(a - d, dp.size - 1) + 1] } } } }.let { (it.sum() % 1_000_000_007).toInt() } }